SELECT n.tableoid::pg_catalog.oid::pg_catalog.text AS catalog_class_oid, n.oid::pg_catalog.text AS object_oid, n.nspowner::pg_catalog.text AS owner_oid, n.nspacl::pg_catalog.text AS nspacl_native_text, pg_catalog.array_dims(n.nspacl) AS nspacl_native_dimensions, pg_catalog.to_jsonb(n)::pg_catalog.text AS original_catalog_row_json FROM pg_catalog.pg_namespace n WHERE n.oid = ANY($1::pg_catalog.oid[]) ORDER BY n.oid